import React,{useEffect,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity,ArrowUpRight,CalendarDays,Check,ChevronRight,Download,FileText,Folder,GitBranch,Image,Link2,ListTodo,Loader2,MessageSquare,Mic,Plus,Search,Send,Settings2,ShieldCheck,Sparkles,Square,Sun,Users,Volume2,X,RefreshCw,Lightbulb,PanelRightClose,PanelRightOpen,LogIn} from 'lucide-react';
import * as DropdownMenu from '@radix-ui/react-dropdown-menu';
import * as Switch from '@radix-ui/react-switch';
import * as Tabs from '@radix-ui/react-tabs';
import '@fontsource-variable/inter';
import './style.css';
import {MediaViewer} from './MediaViewer';
import {ModelsPanel} from './ModelsPanel';
import {MediaLibrary} from './MediaLibrary';
import {FilesPanel} from './FilesPanel';
import {AgentsPanel} from './AgentsPanel';
